create table if not exists public.customer_memory (id uuid primary key default gen_random_uuid(), organisation_id text not null references public.organisations(id) on delete cascade, customer_id uuid not null references public.customers(id) on delete cascade, memory_type text not null default 'customer_alias', source_value text not null, normalized_value text not null, created_by text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (organisation_id, customer_id, memory_type, normalized_value)); create index if not exists customer_memory_lookup_idx on public.customer_memory (organisation_id, memory_type, normalized_value); alter table public.customer_memory enable row level security;